def matrix_exponentiation(mat, exp, mod):
    result = [[1 if i == j else 0 for j in range(len(mat))] for i in range(len(mat))]
    base = mat
    while exp > 0:
        if exp % 2 == 1:
            result = matrix_mult(result, base, mod)
        base = matrix_mult(base, base, mod)
        exp //= 2
    return result

