        for j in range(N):
            if (i + 1) * (j + 1) <= N:
                transition_matrix[i][j] = 1

    # Sum up the first row to get the number of ways to start a sequence
    initial_state = [1] * N

    # Exponentiate the transition matrix
    transition_matrix_exp = matrix_exponentiation(transition_matrix, K - 1, MOD)

    # Calculate the result by multiplying the initial state with the exponentiated matrix
    result = sum(sum(initial_state[i] * transition_matrix_exp[i][j] for i in range(N)) for j in range(N)) % MOD

