def count_sequences(N, K):
    # Precompute prime factors of N
    def prime_factors(n):
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    factors = prime_factors(N)
    factor_count = len(factors)

    # Dynamic programming table
    dp = [[0] * (factor_count + 1) for _ in range(K + 1)]
    dp[0][0] = 1

    # Fill the DP table
    for k in range(1, K + 1):
        for i in range(factor_count + 1):
            for j in range(i, factor_count + 1):
                if i == 0 or j == 0:
                    dp[k][j] = (dp[k][j] + dp[k-1][i]) % MOD
                else:
                    if factors[i-1] * factors[j-1] <= N:
                        dp[k][j] = (dp[k][j] + dp[k-1][i]) % MOD

    # Sum up all possibilities
    result = sum(dp[K]) % MOD
    return result

